REVOKE ALL ON FUNCTION public.create_campus_profile() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.audit_student_change() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
REVOKE UPDATE ON public.campus_interventions FROM authenticated;
GRANT UPDATE (status, outcome) ON public.campus_interventions TO authenticated;
ALTER POLICY interventions_update ON public.campus_interventions USING (public.has_role(auth.uid(),'admin') OR (created_by=auth.uid() AND public.has_role(auth.uid(),'faculty') AND EXISTS (SELECT 1 FROM public.student_records s WHERE s.id=student_id AND s.faculty_id=auth.uid()))) WITH CHECK (public.has_role(auth.uid(),'admin') OR (created_by=auth.uid() AND public.has_role(auth.uid(),'faculty') AND EXISTS (SELECT 1 FROM public.student_records s WHERE s.id=student_id AND s.faculty_id=auth.uid())));
CREATE INDEX student_records_owner_idx ON public.student_records(owner_id);
CREATE INDEX student_records_faculty_idx ON public.student_records(faculty_id);
CREATE INDEX campus_interventions_student_idx ON public.campus_interventions(student_id);